import groovy.xml.XmlSlurper

// The JDK 21 pull request leg (ci.yml) runs only the @Tag("smoke") ITs of the modules that inherit the root build. A
// sample inherits synapse-parent, which doesn't read that filter, so its ITs are left out of that leg by
// .config/jdk21-pr-excluded-its.txt (Failsafe's excludesFile). This check fails when an IT of a sample that inherits
// synapse-parent (directly or through its sample's aggregator) matches no pattern of that file, so a new sample can't
// silently run every IT on that leg. Projects generated by the archetype ITs build in their own Maven run, which
// doesn't get the file, and aren't checked. basedir is tests/synapse-build-rules-tests/target/it/jdk21-pr-excludes,
// so the repository root is five levels up.
def root = new File(basedir, '../../../../..').canonicalFile
def excludesFile = new File(root, '.config/jdk21-pr-excluded-its.txt')
assert excludesFile.isFile() : "${excludesFile} is missing"

// Ant-style patterns, as Failsafe reads them: ** any directories, * and ? within a name; matched on the class file.
def toRegex = { String pattern ->
    def regex = new StringBuilder()
    for (int i = 0; i < pattern.length(); i++) {
        def ch = pattern.charAt(i)
        if (pattern.startsWith('**/', i)) { regex << '(?:.*/)?'; i += 2 }
        else if (pattern.startsWith('**', i)) { regex << '.*'; i += 1 }
        else if (ch == '*' as char) { regex << '[^/]*' }
        else if (ch == '?' as char) { regex << '[^/]' }
        else { regex << java.util.regex.Pattern.quote(ch as String) }
    }
    ~regex.toString()
}
def patterns = excludesFile.readLines('UTF-8')*.trim().findAll { it && !it.startsWith('#') }.collect(toRegex)
assert patterns : "${excludesFile} has no pattern"

// Whether a module's pom inherits synapse-parent, following <parent> through the samples' own aggregator poms.
def inherits
inherits = { File pom ->
    def parent = new XmlSlurper().parse(pom).parent
    if (parent.size() == 0) {
        return false
    }
    if (parent.artifactId.text().trim() == 'synapse-parent') {
        return true
    }
    def relative = parent.relativePath.size() == 0 ? '../pom.xml' : parent.relativePath.text().trim()
    if (!relative) {
        return false
    }
    def target = new File(pom.parentFile, relative)
    target = target.isDirectory() ? new File(target, 'pom.xml') : target
    return target.isFile() && inherits(target.canonicalFile)
}

def poms = []
new File(root, 'samples').eachFileRecurse(groovy.io.FileType.FILES) { file ->
    if (file.name == 'pom.xml' && !file.path.replace(File.separatorChar, '/' as char).contains('/target/')) {
        poms << file
    }
}
assert poms : 'no sample pom found; the check is reading the wrong directory'

def checked = 0
def uncovered = []
poms.findAll { inherits(it) }.each { pom ->
    def tests = new File(pom.parentFile, 'src/test/java')
    if (!tests.isDirectory()) {
        return
    }
    tests.eachFileRecurse(groovy.io.FileType.FILES) { file ->
        // Failsafe's default includes: IT*.java, *IT.java and *ITCase.java.
        if (file.name ==~ /(IT.*|.*IT|.*ITCase)\.java/) {
            def path = tests.toPath().relativize(file.toPath()).toString().replace(File.separatorChar, '/' as char).replaceAll(/\.java$/, '.class')
            checked++
            if (!patterns.any { it.matcher(path).matches() }) {
                uncovered << "${root.toPath().relativize(pom.parentFile.toPath()).toString().replace(File.separatorChar, '/' as char)}: ${path}".toString()
            }
        }
    }
}
assert checked > 0 : 'no sample IT found; the check is reading the wrong directory'
assert uncovered.isEmpty() : "these ITs of samples that inherit synapse-parent match no pattern of " +
        ".config/jdk21-pr-excluded-its.txt, so the JDK 21 pull request leg would run them all; add the sample's " +
        "package there:\n" + uncovered.join('\n')
true
